#!/usr/bin/env python3
"""Generate docs/research-summary.md: one-screen overview of the researched content and its gaps."""
import json, glob, os
from collections import Counter

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
kit = json.load(open(os.path.join(ROOT, "data/kit.json")))
L = ["# Research summary (generated)", "",
     "Generated by `scripts/research_summary.py`. Research run: 2026-11-05, nine parallel research agents plus follow-ups. "
     "Every value in `data/` cites its sources; this page shows coverage and gaps.", ""]

kinds = Counter()
L += ["## Lenses", "", "| Lens | Sweet spot | Close-up best | Max mag | Confidence | Measured / total sources | Chris Frost |", "|---|---|---|---|---|---|---|"]
for g in kit["lens_groups"]:
    for lid in g["lenses"]:
        p = os.path.join(ROOT, f"data/lenses/{lid}.json")
        if not os.path.exists(p):
            L.append(f"| {lid} | MISSING | | | | | |"); continue
        d = json.load(open(p)); q = d["quick"]
        for s in d["sources"]:
            kinds[s.get("kind")] += 1
        meas = sum(1 for s in d["sources"] if s.get("kind") == "measured")
        mm = max(d["close_focus"].get("max_mag") or [{"value": None}], key=lambda x: x["value"] or 0)["value"]
        cfa = (d.get("chris_frost") or {}).get("access", "?")
        L.append(f"| {d['short']} | {q.get('sweet_spot')} | {q.get('close_up_best')} | {mm}× | {q.get('confidence')} | {meas} / {len(d['sources'])} | {cfa} |")
L.append("")
L += ["Source kinds across all lenses: " + ", ".join(f"{k} {v}" for k, v in kinds.most_common()), ""]

L += ["## Bodies", ""]
for b in kit["bodies"]:
    d = json.load(open(os.path.join(ROOT, f"data/bodies/{b['id']}.json")))
    fw = d.get("firmware", {})
    L.append(f"- **{d['name']}**: {d['sensor']['effective_mp']} MP, pitch {d['sensor']['pixel_pitch_um']} µm, "
             f"IBIS {d['ibis'].get('cipa_stops')} stops, firmware {fw.get('current')} ({fw.get('date')}). "
             f"Open points: {(d.get('research_notes') or '—')[:300]}")
L.append("")

L += ["## Settings", ""]
for p in sorted(glob.glob(os.path.join(ROOT, "data/settings/*.json"))):
    arr = json.load(open(p))
    per = Counter(b for s in arr for b in s.get("available_on", []))
    import re; unv = [s["id"] for s in arr if re.search(r"unverif|not verified|not read|could not|couldn.t|assumed", (s.get("research_notes") or "").lower())]
    L.append(f"- `{os.path.basename(p)}`: {len(arr)} settings (Z8 {per['z8']}, Z5 II {per['z5ii']}, Z50 II {per['z50ii']}). "
             f"Entries flagging unverified details: {', '.join(unv) if unv else 'none'}.")
L.append("")

L += ["## Low-confidence and inferred items to re-check", ""]
for g in kit["lens_groups"]:
    for lid in g["lenses"]:
        d = json.load(open(os.path.join(ROOT, f"data/lenses/{lid}.json")))
        q = d["quick"]
        flags = []
        if q.get("confidence") == "low":
            flags.append("overall confidence low")
        if "infer" in (q.get("close_up_note") or "").lower() or "infer" in (q.get("close_up_best") or "").lower():
            flags.append("close-up aperture inferred, not measured")
        if d["stabilization"].get("synchro_vr") is None and d["stabilization"].get("lens_vr"):
            flags.append("Synchro VR support unverified")
        if flags:
            L.append(f"- {d['short']}: " + "; ".join(flags))
L.append("")
open(os.path.join(ROOT, "docs/research-summary.md"), "w").write("\n".join(L) + "\n")
print("wrote docs/research-summary.md")
